import { useState, type FC, type ReactNode } from 'react';
import {
  SalesforceOpportunityShell,
  TackleCard
} from '@tackle-io/design-system';
import { NAV_ITEMS } from '../config/navigation';
import {
  DEFAULT_HIGHLIGHTS,
  DEFAULT_PATH_STAGES,
  DEFAULT_TABS,
  UTILITY_BAR
} from '../data/opportunity';
import { ActivityTab } from '../components/opportunity-tabs/ActivityTab';
import { DetailsTab } from '../components/opportunity-tabs/DetailsTab';
import { ChatterTab } from '../components/opportunity-tabs/ChatterTab';

const SfButton: FC<{ children: ReactNode; primary?: boolean }> = ({
  children,
  primary
}) => (
  <button
    type="button"
    style={{
      padding: '6px 14px',
      borderRadius: 4,
      border: primary ? 'none' : '1px solid #c9c9c9',
      background: primary ? '#0176d3' : '#fff',
      color: primary ? '#fff' : '#181818',
      fontSize: 13,
      fontWeight: 600,
      cursor: 'pointer'
    }}
  >
    {children}
  </button>
);

export function OpportunityPage() {
  const [activeTab, setActiveTab] = useState('details');

  const tabContent: Record<string, ReactNode> = {
    activity: <ActivityTab />,
    details: <DetailsTab />,
    chatter: <ChatterTab />
  };

  return (
    <SalesforceOpportunityShell
      navItems={NAV_ITEMS}
      activeNavItem="Opportunities"
      opportunityName="Acme Corp Summer '26"
      headerActions={
        <>
          <SfButton>+ Follow</SfButton>
          <SfButton primary>New Case</SfButton>
        </>
      }
      highlights={DEFAULT_HIGHLIGHTS}
      pathStages={DEFAULT_PATH_STAGES}
      onMarkStageComplete={() => {}}
      tabs={DEFAULT_TABS}
      activeTab={activeTab}
      onTabChange={setActiveTab}
      sidebarContent={<TackleCard variant="prospect" />}
      utilityBarItems={UTILITY_BAR}
    >
      {tabContent[activeTab]}
    </SalesforceOpportunityShell>
  );
}
